import React, {
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { Clock as GrommetClockIcon } from 'grommet-icons/icons/Clock';

import { AnnounceContext } from '../../contexts/AnnounceContext';
import { MessageContext } from '../../contexts/MessageContext';
import { useForwardedRef } from '../../utils';
import { normalizeStep } from '../../utils/dates';
import { useThemeValue } from '../../utils/useThemeValue';
import { getSectionTokenFromType } from '../../utils/sectionHelpers';
import { Box } from '../Box';
import { Button } from '../Button';
import { FormContext } from '../Form';
import { FormFieldContext } from '../FormField/FormFieldContext';
import { Keyboard } from '../Keyboard';
import {
  StyledTimeInputDisplay,
  StyledTimeInputField,
  StyledTimeInputSegment,
  StyledTimeInputSeparator,
  StyledTimeInputContainer,
  StyledTimeInput,
} from './StyledTimeInput';
import { TimeInputPopup } from './TimeInputPopup';
import { TimeInputPropTypes } from './propTypes';
import { useSectionedTimeField } from './useSectionedTimeField';
import {
  getSectionAriaMeta,
  getSectionName,
  pad,
  sectionTypeFromSection,
  sectionKey,
  SECTION_HOUR,
  SECTION_MINUTE,
  SECTION_PERIOD,
  SECTION_SECOND,
} from './utils';

const getDisplaySectionPrefix = (section, index) => {
  if (index === 0) return '';
  return section === SECTION_PERIOD ? ' ' : ':';
};

const getSectionOrder = (format, showSeconds) => {
  const numericSections = showSeconds
    ? [SECTION_HOUR, SECTION_MINUTE, SECTION_SECOND]
    : [SECTION_HOUR, SECTION_MINUTE];

  if (format === '12') {
    return [...numericSections, SECTION_PERIOD];
  }

  return numericSections;
};

const getContainerFill = (container = {}) => {
  const fillWidth = container.width === undefined;
  const fillHeight = container.height === undefined;

  if (fillWidth && fillHeight) return true;
  if (fillWidth) return 'horizontal';
  if (fillHeight) return 'vertical';
  return false;
};

const resolveDropButtonIcon = (icon) => {
  if (React.isValidElement(icon)) {
    return React.cloneElement(icon, {
      'aria-hidden': icon.props['aria-hidden'] ?? true,
    });
  }
  if (typeof icon === 'function' || icon?.$$typeof)
    return React.createElement(icon, { 'aria-hidden': true });
  return icon;
};

const buildPlaceholder = (sectionOrder) =>
  sectionOrder
    .map((section, index) => {
      const token = getSectionTokenFromType(sectionTypeFromSection(section));
      return `${getDisplaySectionPrefix(section, index)}${token}`;
    })
    .join('');

// When `format` isn't explicitly provided, default to the 12/24-hour
// convention the browser's default locale uses, rather than hardcoding one.
const getDefaultFormat = () => {
  try {
    const { hour12 } = new Intl.DateTimeFormat(undefined, {
      hour: 'numeric',
    }).resolvedOptions();
    return hour12 ? '12' : '24';
  } catch {
    return '24';
  }
};

const DEFAULT_FORMAT = getDefaultFormat();

const TimeInput = forwardRef(
  (
    {
      defaultValue,
      disabled,
      // Internal-only flag used by DateTimeInput to suppress focus on open.
      // It is intentionally not included in PropTypes or TS types because it
      // is not part of the public TimeInput API.
      focusOnOpen = true,
      format = DEFAULT_FORMAT,
      id,
      inline = false,
      messages,
      minuteStep = 1,
      name,
      onChange,
      onPartialChange,
      readOnly = false,
      showSeconds = false,
      value: valueArg,
      ...rest
    },
    refArg,
  ) => {
    const { theme, passThemeFlag } = useThemeValue();
    const announce = useContext(AnnounceContext);
    const { format: formatMessage } = useContext(MessageContext);
    const formContext = useContext(FormContext);
    const { setFocusIndicator: setFieldFocusIndicator } =
      useContext(FormFieldContext);
    const { useFormInput } = formContext;

    const inputRef = useForwardedRef(refArg);
    const containerRef = useRef();

    const [value, setValue] = useFormInput({
      name,
      value: valueArg,
      initialValue: defaultValue || '',
    });

    if (inline && (disabled || readOnly)) {
      console.warn(
        'TimeInput is rendered inline and is either disabled or read-only. ' +
          'TimeInput ignores disabled and readOnly props when rendered inline.',
      );
    }
    const { inForm } = formContext.useFormField({});
    const formFieldLabelId = inForm && id ? `grommet-${id}__label` : undefined;
    const groupLabel = formFieldLabelId
      ? undefined
      : formatMessage({ id: 'timeInput.inputLabel', messages });

    const [open, setOpen] = useState(false);
    const [iconFocused, setIconFocused] = useState(false);
    const [segmentFocused, setSegmentFocused] = useState(false);
    const segmentRefs = useRef({});

    const {
      // Keep internal visual parity with TextInput/Form behavior while
      // maintaining the agreed external TimeInput API surface.
      plain: plainProp,
      focusIndicator: focusIndicatorProp,
      // FormField injects these on error; they must reach the focusable
      // spinbutton segments, not the aria-hidden mirror input, or a screen
      // reader user focusing a segment never hears the error is invalid or
      // where its description text lives.
      'aria-describedby': ariaDescribedBy,
      'aria-invalid': ariaInvalid,
      ...inputRest
    } = rest;

    // FormField merges its generated error id into aria-describedby
    // alongside any id the consumer already had on the child. Split those
    // back apart so a pre-existing description stays on every segment,
    // while the error id itself is only added to the segment(s) it's about.
    const errorId = id ? `grommet-${id}__error` : undefined;
    const describedByTokens = ariaDescribedBy
      ? ariaDescribedBy.split(' ').filter(Boolean)
      : [];
    const hasErrorDescribedBy =
      !!errorId && describedByTokens.includes(errorId);
    const consumerDescribedBy =
      describedByTokens.filter((token) => token !== errorId).join(' ') ||
      undefined;

    const normalizedMinuteStep = useMemo(
      () => normalizeStep(minuteStep),
      [minuteStep],
    );

    const handleInvalid = useCallback(() => {
      const error = formatMessage({ id: 'timeInput.invalidTime', messages });
      announce(error, 'assertive');
    }, [announce, formatMessage, messages]);

    const announceCurrentValue = useCallback(
      (nextSections) => {
        if (
          nextSections.hour === undefined ||
          nextSections.minute === undefined ||
          (showSeconds && nextSections.second === undefined)
        )
          return;

        const period = format === '12' ? ` ${nextSections.period || 'AM'}` : '';
        const messageId = showSeconds
          ? 'timeInput.currentValue'
          : 'timeInput.currentValueWithoutSeconds';

        announce(
          formatMessage({
            id: messageId,
            messages,
            values: {
              hour: nextSections.hour,
              minute: nextSections.minute,
              ...(showSeconds ? { second: nextSections.second } : {}),
              period,
            },
          }),
          'polite',
        );
      },
      [announce, format, formatMessage, messages, showSeconds],
    );

    const sectionOrder = useMemo(
      () => getSectionOrder(format, showSeconds),
      [format, showSeconds],
    );

    const firstSection = sectionOrder[0] || SECTION_HOUR;
    const lastSection = sectionOrder[sectionOrder.length - 1] || SECTION_HOUR;

    const {
      activeSection,
      applyDigit,
      clearActiveSection,
      commitSections,
      displayValue,
      incrementSection,
      moveSection,
      parsePasted,
      sections,
      setActiveSection,
      setSectionValue,
      pendingDigits,
    } = useSectionedTimeField({
      format,
      sectionOrder,
      minuteStep: normalizedMinuteStep,
      value,
      onCommit: (_nextSections, nextValue, _changedSection) => {
        // Fire partial change on every commit so consumers can update
        // display state even before all sections are filled.
        onPartialChange?.(_nextSections, _changedSection);
        if (!nextValue) {
          setValue('');
          onChange?.({ value: undefined });
          return;
        }

        setValue(nextValue);
        onChange?.({ value: nextValue });
        announceCurrentValue(_nextSections);
      },
      onInvalid: handleInvalid,
    });

    // Builds the announcement text for a given section: its current value
    // (e.g. "3 hours") if it has one, or just the section name (e.g. "hours
    // selected") when it doesn't yet. Called explicitly on every navigation
    // and edit interaction so screen readers hear meaningful feedback instead
    // of the raw separator/placeholder characters in the native input value.
    const getSectionValueAnnouncement = useCallback(
      (section) => {
        const sectionName = getSectionName(
          section,
          format,
          formatMessage,
          messages,
        );

        if (section === SECTION_PERIOD) {
          if (sections.period === undefined) {
            return formatMessage({
              id: 'timeInput.activeSection',
              messages,
              values: { section: sectionName },
            });
          }

          return formatMessage({
            id: 'timeInput.activePeriodValue',
            messages,
            values: { period: sections.period },
          });
        }

        const sectionValue = sections[sectionKey(section)];

        if (sectionValue === undefined) {
          return formatMessage({
            id: 'timeInput.activeSection',
            messages,
            values: { section: sectionName },
          });
        }

        return formatMessage({
          id: 'timeInput.activeSectionValue',
          messages,
          values: {
            value: sectionValue,
            section: sectionName,
          },
        });
      },
      [format, formatMessage, messages, sections],
    );

    const focusSection = useCallback((section) => {
      const target = segmentRefs.current[section];
      if (target) {
        target.focus();
      }
    }, []);

    const placeholder = useMemo(
      () => buildPlaceholder(sectionOrder),
      [sectionOrder],
    );
    const inputValue = displayValue || placeholder;
    const hasDisplayValue = !!displayValue;
    const displaySections = useMemo(() => {
      // Merge sections with pending digits for display
      const displaySectionsData = { ...sections };
      const pendingSection = Object.keys(pendingDigits)[0];
      if (pendingSection && pendingDigits[pendingSection] !== undefined) {
        displaySectionsData[pendingSection] = pendingDigits[pendingSection];
      }

      return sectionOrder.map((section, index) => {
        const key = sectionKey(section);
        const sectionValue = displaySectionsData[key];
        let text;
        if (sectionValue === undefined) {
          text = getSectionTokenFromType(sectionTypeFromSection(section));
        } else if (section === SECTION_PERIOD) {
          text = sectionValue;
        } else {
          text = pad(sectionValue);
        }

        return {
          ariaMeta: getSectionAriaMeta({ section, format, sections }),
          section,
          prefix: getDisplaySectionPrefix(section, index),
          text,
          filled: sectionValue !== undefined,
        };
      });
    }, [format, pendingDigits, sectionOrder, sections]);

    // A required-field error is caused by whichever section(s) are still
    // empty, so only announce it there; once every section has a value the
    // error must be about the value as a whole, so announce it everywhere.
    const allSectionsFilled = displaySections.every((entry) => entry.filled);

    const onDisplaySectionMouseDown = useCallback(
      (section, event) => {
        if (readOnly) return;
        if (disabled) return;
        if (event.button !== 0) return;
        if (event.defaultPrevented) return;
        event.preventDefault();
        event.stopPropagation();
        setSegmentFocused(true);
        setActiveSection(section);
        focusSection(section);
      },
      [disabled, focusSection, readOnly, setSegmentFocused, setActiveSection],
    );

    const onDisplayMouseDown = useCallback(
      (event) => {
        if (readOnly) return;
        if (event.button !== 0) return;
        if (event.defaultPrevented) return;

        const sectionNode = event.target.closest?.('[data-section]');
        if (sectionNode?.dataset?.section !== undefined) {
          const section = Number(sectionNode.dataset.section);
          if (!Number.isNaN(section)) {
            onDisplaySectionMouseDown(section, event);
            return;
          }
        }

        const nodes = Array.from(
          event.currentTarget.querySelectorAll('[data-section]'),
        );

        if (nodes.length) {
          const x = event.clientX;

          const sectionsWithRects = nodes
            .map((node) => ({
              node,
              rect: node.getBoundingClientRect(),
            }))
            .sort((a, b) => a.rect.left - b.rect.left);

          const sectionFromBounds = sectionsWithRects.find(
            ({ rect }) => x >= rect.left && x <= rect.right,
          );

          if (sectionFromBounds?.node?.dataset?.section !== undefined) {
            const section = Number(sectionFromBounds.node.dataset.section);
            if (!Number.isNaN(section)) {
              onDisplaySectionMouseDown(section, event);
              return;
            }
          }

          const zones = sectionsWithRects.map(({ rect }, index) => {
            const prev = sectionsWithRects[index - 1];
            const next = sectionsWithRects[index + 1];

            const start =
              prev !== undefined
                ? (prev.rect.right + rect.left) / 2
                : Number.NEGATIVE_INFINITY;
            const end =
              next !== undefined
                ? (rect.right + next.rect.left) / 2
                : Number.POSITIVE_INFINITY;

            return { index, start, end };
          });

          const zone =
            zones.find(({ start, end }) => x >= start && x <= end) ||
            zones[0] ||
            null;

          if (zone) {
            const matched = sectionsWithRects[zone.index]?.node;
            if (matched?.dataset?.section !== undefined) {
              const section = Number(matched.dataset.section);
              if (!Number.isNaN(section)) {
                onDisplaySectionMouseDown(section, event);
                return;
              }
            }
          }
        }

        event.preventDefault();
        setSegmentFocused(true);
        setActiveSection(firstSection);
        focusSection(firstSection);
      },
      [
        firstSection,
        focusSection,
        onDisplaySectionMouseDown,
        readOnly,
        setSegmentFocused,
        setActiveSection,
      ],
    );

    const openPicker = useCallback(() => {
      if (disabled || readOnly) return;
      setActiveSection(firstSection);
      setOpen(true);
    }, [disabled, firstSection, readOnly, setActiveSection]);

    const closePicker = useCallback(() => {
      setOpen(false);
      setTimeout(() => {
        focusSection(activeSection);
      }, 0);
    }, [activeSection, focusSection]);

    const onSegmentFocus = useCallback(
      (section) => {
        setFieldFocusIndicator?.(true);
        if (!segmentFocused && !readOnly && !disabled && !open) {
          announce(formatMessage({ id: 'timeInput.openDrop', messages }));
        }
        setSegmentFocused(true);
        if (readOnly || disabled) return;
        setActiveSection(section);
      },
      [
        announce,
        disabled,
        formatMessage,
        messages,
        open,
        readOnly,
        segmentFocused,
        setFieldFocusIndicator,
        setActiveSection,
      ],
    );

    const onSegmentBlur = useCallback(() => {
      requestAnimationFrame(() => {
        const { activeElement } = document;
        const isSegmentFocused = Object.values(segmentRefs.current).includes(
          activeElement,
        );
        const isInsideTimeInput = containerRef.current?.contains(activeElement);
        if (!isSegmentFocused || !isInsideTimeInput) {
          setSegmentFocused(false);
        }
      });
    }, []);

    const onSegmentKeyDown = useCallback(
      (section, event) => {
        if (readOnly || disabled) return;
        const { key, ctrlKey, metaKey, altKey } = event;
        if (ctrlKey || metaKey || (altKey && key !== 'ArrowDown')) return;

        if (activeSection !== section) {
          setActiveSection(section);
        }

        if (key === 'ArrowRight') {
          event.preventDefault();
          const next = moveSection(1);
          setActiveSection(next);
          focusSection(next);
          event.stopPropagation();
          return;
        }
        if (key === 'ArrowLeft') {
          event.preventDefault();
          event.stopPropagation();
          const next = moveSection(-1);
          setActiveSection(next);
          focusSection(next);
          return;
        }
        if (key === 'Home') {
          event.preventDefault();
          event.stopPropagation();
          setActiveSection(firstSection);
          focusSection(firstSection);
          return;
        }
        if (key === 'End') {
          event.preventDefault();
          event.stopPropagation();
          setActiveSection(lastSection);
          focusSection(lastSection);
          return;
        }
        if (key === 'ArrowUp') {
          event.preventDefault();
          event.stopPropagation();
          incrementSection(section, open ? -1 : 1);
          return;
        }
        if (key === 'ArrowDown') {
          if (altKey) {
            event.preventDefault();
            event.stopPropagation();
            openPicker();
            return;
          }
          event.preventDefault();
          event.stopPropagation();
          incrementSection(section, open ? 1 : -1);
          return;
        }
        if (key === 'Delete' || key === 'Backspace') {
          event.preventDefault();
          event.stopPropagation();
          clearActiveSection();
          return;
        }
        if ((key === 'Enter' || key === 'Escape') && open) {
          event.preventDefault();
          event.stopPropagation();
          closePicker();
          return;
        }
        if (key === ' ' || key === 'Spacebar') {
          event.preventDefault();
          event.stopPropagation();
          openPicker();
          return;
        }

        if (format === '12' && section === SECTION_PERIOD) {
          const lower = key.toLowerCase();
          if (lower === 'a') {
            event.preventDefault();
            event.stopPropagation();
            setSectionValue(SECTION_PERIOD, 'AM');
          } else if (lower === 'p') {
            event.preventDefault();
            event.stopPropagation();
            setSectionValue(SECTION_PERIOD, 'PM');
          }
          return;
        }

        if (/^\d$/.test(key)) {
          event.preventDefault();
          event.stopPropagation();
          const next = applyDigit(Number(key));
          const targetSection = next ?? section;
          setActiveSection(targetSection);
          if (targetSection !== section) {
            // moving to a different section focus for digit',
            focusSection(targetSection);
          }
        }
      },
      [
        activeSection,
        applyDigit,
        clearActiveSection,
        closePicker,
        disabled,
        firstSection,
        focusSection,
        format,
        incrementSection,
        lastSection,
        moveSection,
        open,
        openPicker,
        readOnly,
        setActiveSection,
        setSectionValue,
      ],
    );

    useEffect(() => {
      if (!segmentFocused) return;
      if (readOnly || disabled) return;

      const activeSegment = segmentRefs.current[activeSection];
      if (activeSegment && document.activeElement !== activeSegment) {
        activeSegment.focus();
      }
    }, [activeSection, disabled, readOnly, segmentFocused]);

    const onSegmentPaste = useCallback(
      (event) => {
        if (readOnly) {
          event.preventDefault();
          return;
        }
        const pasted = event.clipboardData.getData('text');
        const parsed = parsePasted(pasted);
        if (!parsed) {
          handleInvalid();
          event.preventDefault();
          return;
        }

        commitSections(parsed);
        event.preventDefault();
      },
      [commitSections, handleInvalid, parsePasted, readOnly],
    );

    const hoursOptions = useMemo(
      () =>
        format === '12'
          ? [12, ...Array.from({ length: 11 }, (_, index) => index + 1)]
          : Array.from({ length: 24 }, (_, index) => index),
      [format],
    );

    const minuteOptions = useMemo(
      () =>
        Array.from(
          { length: Math.ceil(60 / normalizedMinuteStep) },
          (_, index) => index * normalizedMinuteStep,
        ).filter((valueAtIndex) => valueAtIndex < 60),
      [normalizedMinuteStep],
    );

    const secondOptions = useMemo(
      () => Array.from({ length: 60 }, (_, index) => index),
      [],
    );

    const showActiveSection =
      (segmentFocused || open) && !readOnly && !disabled;
    const containerTheme = theme.timeInput?.container;
    const dropButtonTheme = theme.timeInput?.dropButton;
    let dropButtonKind = 'toolbar';
    let dropButtonIcon = <GrommetClockIcon aria-hidden="true" />;

    if (typeof dropButtonTheme === 'string') {
      dropButtonKind = dropButtonTheme;
    } else if (
      dropButtonTheme &&
      typeof dropButtonTheme === 'object' &&
      !React.isValidElement(dropButtonTheme) &&
      !dropButtonTheme.$$typeof
    ) {
      const { icon, kind, ...buttonTheme } = dropButtonTheme;
      dropButtonIcon = resolveDropButtonIcon(icon ?? dropButtonIcon);

      if (kind) {
        dropButtonKind = kind;
      } else {
        const hasButtonTheme = Object.keys(buttonTheme).length > 0;
        dropButtonKind = hasButtonTheme ? buttonTheme : 'toolbar';
      }
    }

    if (inline) {
      return (
        <TimeInputPopup
          inline
          activeSection={activeSection}
          format={format}
          formatMessage={formatMessage}
          focusOnOpen={inline ? false : focusOnOpen}
          hoursOptions={hoursOptions}
          incrementSection={incrementSection}
          messages={messages}
          minuteOptions={minuteOptions}
          sectionOrder={sectionOrder}
          secondOptions={secondOptions}
          sections={sections}
          setActiveSection={setActiveSection}
          setSectionValue={setSectionValue}
          {...inputRest}
        />
      );
    }

    return (
      <Keyboard onEsc={open ? closePicker : undefined}>
        <Box>
          <StyledTimeInputContainer
            ref={containerRef}
            direction="row"
            border={!plainProp}
            fill={getContainerFill(containerTheme)}
            {...containerTheme}
            round={
              theme.timeInput?.container?.round ??
              theme.global?.control?.border?.radius
            }
            disabled={disabled}
            readOnlyProp={readOnly}
            focusIndicator={(focusIndicatorProp ?? true) && !iconFocused}
            {...passThemeFlag}
          >
            <StyledTimeInputField {...passThemeFlag}>
              <StyledTimeInputDisplay
                {...theme.timeInput?.value}
                align="center"
                direction="row"
                overflow="hidden"
                role="group"
                aria-label={groupLabel}
                aria-labelledby={formFieldLabelId}
                onMouseDown={onDisplayMouseDown}
                {...passThemeFlag}
              >
                {displaySections.map(
                  ({ ariaMeta, section, prefix, text, filled }) => {
                    const describeSegment = !filled || allSectionsFilled;

                    return (
                      <React.Fragment key={section}>
                        {!!prefix && (
                          <StyledTimeInputSeparator
                            $filled={hasDisplayValue}
                            {...passThemeFlag}
                          >
                            {prefix}
                          </StyledTimeInputSeparator>
                        )}
                        <StyledTimeInputSegment
                          ref={(segmentNode) => {
                            segmentRefs.current[section] = segmentNode;
                          }}
                          responsive={false}
                          tabIndex={
                            !readOnly && !disabled && activeSection === section
                              ? 0
                              : -1
                          }
                          $active={
                            showActiveSection && activeSection === section
                          }
                          $filled={filled}
                          onFocus={() => onSegmentFocus(section)}
                          onBlur={onSegmentBlur}
                          onKeyDown={(event) =>
                            onSegmentKeyDown(section, event)
                          }
                          onPaste={onSegmentPaste}
                          data-active={
                            showActiveSection && activeSection === section
                          }
                          data-section={section}
                          {...passThemeFlag}
                          aria-label={getSectionName(
                            section,
                            format,
                            formatMessage,
                            messages,
                          )}
                          role="spinbutton"
                          aria-disabled={disabled || undefined}
                          aria-readonly={readOnly || undefined}
                          aria-invalid={
                            (ariaInvalid && describeSegment) || undefined
                          }
                          aria-describedby={
                            [
                              consumerDescribedBy,
                              describeSegment && hasErrorDescribedBy
                                ? errorId
                                : undefined,
                            ]
                              .filter(Boolean)
                              .join(' ') || undefined
                          }
                          aria-valuenow={ariaMeta.now}
                          aria-valuemin={ariaMeta.min}
                          aria-valuemax={ariaMeta.max}
                          aria-valuetext={getSectionValueAnnouncement(section)}
                        >
                          {text}
                        </StyledTimeInputSegment>
                      </React.Fragment>
                    );
                  },
                )}
              </StyledTimeInputDisplay>
              <StyledTimeInput
                tabIndex={-1}
                {...inputRest}
                id={id}
                ref={inputRef}
                value={inputValue}
                aria-hidden="true"
                disabled={disabled}
                readOnly
                focusIndicator={false}
                plain
              />
            </StyledTimeInputField>
            {name && (
              <input
                aria-hidden="true"
                name={name}
                readOnly
                tabIndex={-1}
                type="hidden"
                value={value || ''}
              />
            )}
            {!readOnly && (
              <Button
                kind={dropButtonKind}
                icon={dropButtonIcon}
                disabled={disabled}
                aria-label={formatMessage({
                  id: 'timeInput.chooseTime',
                  messages,
                })}
                aria-haspopup="dialog"
                aria-expanded={open}
                aria-controls={id ? `${id}__drop` : undefined}
                onFocus={() => {
                  setIconFocused(true);
                  setFieldFocusIndicator?.(false);
                }}
                onBlur={() => {
                  setIconFocused(false);
                }}
                onClick={open ? closePicker : openPicker}
              />
            )}
          </StyledTimeInputContainer>
          {open && (
            <TimeInputPopup
              activeSection={activeSection}
              align={{ top: 'bottom', left: 'left' }}
              dropProps={{ stretch: false }}
              format={format}
              formatMessage={formatMessage}
              focusOnOpen={focusOnOpen}
              hoursOptions={hoursOptions}
              id={id}
              incrementSection={incrementSection}
              label={formatMessage({ id: 'timeInput.chooseTime', messages })}
              messages={messages}
              minuteOptions={minuteOptions}
              sectionOrder={sectionOrder}
              onClose={closePicker}
              onFocusLeave={closePicker}
              secondOptions={secondOptions}
              sections={sections}
              setActiveSection={setActiveSection}
              setSectionValue={setSectionValue}
              target={containerRef.current}
            />
          )}
        </Box>
      </Keyboard>
    );
  },
);

TimeInput.displayName = 'TimeInput';
TimeInput.propTypes = TimeInputPropTypes;

export { TimeInput };
